/* Brendy CMS — native sortable compatibility adapter, Brendigo LTD.
 * First-party implementation. Retains the historical jQuery helper API. */
(function ($) {
    "use strict";
    if (!$ || !$.fn) return;
    const instances = new WeakMap();
    let drag = null;

    function items(state) {
        return $(state.element).children(state.options.items || "*").toArray()
            .filter(node => !node.classList.contains("sortable-placeholder"));
    }
    function itemAt(state, target) {
        return items(state).find(node => node === target || node.contains(target)) || null;
    }
    function sync(state) {
        for (const node of items(state)) {
            if (!state.original.has(node)) state.original.set(node, node.getAttribute("draggable"));
            node.setAttribute("draggable", state.enabled ? "true" : "false");
        }
    }
    function clearDrag() {
        if (!drag) return;
        drag.item.classList.remove("sortable-dragging");
        drag.placeholder.remove();
        drag = null;
    }
    function accepts(state) {
        if (!drag || !state.enabled) return false;
        if (state === drag.source) return true;
        const selector = drag.source.options.connectWith;
        if (typeof selector !== "string" || !selector || state.options.connectWith !== selector) return false;
        try { return $(state.element).is(selector); } catch (_) { return false; }
    }
    function destroy(state) {
        if (drag && (drag.source === state || drag.placeholder.parentElement === state.element)) clearDrag();
        for (const [name, handler] of state.listeners) state.element.removeEventListener(name, handler);
        for (const [node, original] of state.original) {
            if (original === null) node.removeAttribute("draggable");
            else node.setAttribute("draggable", original);
        }
        instances.delete(state.element);
    }
    function initialize(element, options) {
        const existing = instances.get(element);
        if (existing) destroy(existing);
        const state = {element, options: $.extend({connectWith:false}, options), enabled:true,
            original:new Map(), listeners:[], armed:null};
        instances.set(element, state);
        const on = (name, handler) => { element.addEventListener(name, handler); state.listeners.push([name, handler]); };
        on("mousedown", event => {
            const node = itemAt(state, event.target);
            state.armed = node && (!state.options.handle || $(event.target).closest(state.options.handle, node.parentElement).length) ? node : null;
        });
        on("mouseup", () => { state.armed = null; });
        on("dragstart", event => {
            const node = itemAt(state, event.target);
            if (!state.enabled || !node || (state.options.handle && state.armed !== node)) { event.preventDefault(); return; }
            if (!event.dataTransfer) { event.preventDefault(); return; }
            clearDrag();
            const tag = /^(UL|OL)$/.test(element.tagName) ? "li" : element.tagName === "TBODY" ? "tr" : "div";
            const placeholder = document.createElement(tag);
            placeholder.classList.add("sortable-placeholder");
            if (typeof state.options.placeholderClass === "string") {
                for (const name of state.options.placeholderClass.split(/\s+/)) if (name) placeholder.classList.add(name);
            }
            placeholder.textContent = "\u00a0";
            if (state.options.forcePlaceholderSize) placeholder.style.height = node.getBoundingClientRect().height + "px";
            drag = {source:state, item:node, index:items(state).indexOf(node), placeholder};
            node.classList.add("sortable-dragging");
            event.dataTransfer.effectAllowed = "move";
            event.dataTransfer.setData("text/plain", "brendy-sortable");
            state.armed = null;
        });
        on("dragover", event => {
            if (!accepts(state)) return;
            event.preventDefault();
            if (event.dataTransfer) event.dataTransfer.dropEffect = "move";
            const node = itemAt(state, event.target);
            if (node === drag.item) return;
            if (!node) {
                if (!items(state).filter(item => item !== drag.item).length) element.appendChild(drag.placeholder);
                return;
            }
            const rect = node.getBoundingClientRect();
            element.insertBefore(drag.placeholder, event.clientY < rect.top + rect.height / 2 ? node : node.nextSibling);
        });
        on("drop", event => {
            if (!accepts(state) || drag.placeholder.parentElement !== element) return;
            event.preventDefault(); event.stopPropagation();
            const {source,item,index,placeholder} = drag;
            element.insertBefore(item, placeholder);
            const changed = source !== state || items(state).indexOf(item) !== index;
            if (source !== state && source.original.has(item)) {
                state.original.set(item, source.original.get(item));
                source.original.delete(item);
            }
            clearDrag(); sync(state); sync(source);
            if (changed) $(element).trigger("sortupdate", {item:$(item)});
            if (source !== state) $(element).trigger("sortconnect", {item:$(item)});
        });
        on("dragend", clearDrag);
        sync(state);
    }
    $.fn.sortable = function (option) {
        return this.each(function () {
            const state = instances.get(this);
            if (typeof option === "string") {
                if (!state) return;
                if (option === "destroy") destroy(state);
                else if (option === "enable" || option === "disable") {
                    state.enabled = option === "enable";
                    if (!state.enabled && drag && drag.source === state) clearDrag();
                    sync(state);
                } else if (option === "refresh") sync(state);
                return;
            }
            initialize(this, option || {});
        });
    };
})(window.jQuery);
